MOTIF_NAME = 'minor_piece_development'
MOTIF_DESCRIPTION = 'Side to move has at least 3 of 4 minor pieces developed off starting squares.'
def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    if stm:
        starting_squares = {chess.B1, chess.G1, chess.C1, chess.F1}
    else:
        starting_squares = {chess.B8, chess.G8, chess.C8, chess.F8}
    developed = 0
    for piece_type in [chess.KNIGHT, chess.BISHOP]:
        for sq in board.pieces(piece_type, stm):
            if sq not in starting_squares:
                developed += 1
    return developed >= 3
